import { z } from 'zod'

import { objectNoSchema, qrTokenSchema } from './object.js'
import { textTemplateKeySchema } from './text-template.js'

/**
 * Public report form API schemas (`specs/06-report-form.md` §7.3, WP-M2-04b).
 *
 * The endpoint is unauthenticated, so every rule of §7.3.1 lives here and the API
 * answers only error **codes** — never translated text. `ticket_no` is generated by
 * the database (§4.11), `status_token` with the ticket (§7.3.4), and `photos` are
 * the base64 data URLs of §7.4 whose bytes the service verifies.
 */

const trimmedText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .optional()
    .transform((value) => (value === '' ? undefined : value))

/** Ticket number as printed on tickets (`specs/02-data-model.md` §4.11,
 * `ST-2026-0001`). */
export const ticketNoSchema = z.string().trim().regex(/^ST-\d{4}-\d{4,}$/)

/** `text_templates.key` values — machine keys, never translated text (plan §3). */
export const faultTemplateKeySchema = textTemplateKeySchema

export const publicReportContactSchema = z.object({
  name: trimmedText(120),
  phone: trimmedText(60),
  email: trimmedText(320).pipe(z.email().optional()),
})

/**
 * One photo as a data URL (`specs/06-report-form.md` §7.4, WP-M2-04c): the canvas
 * output of the client compressor travels inside the same JSON body. Only
 * `image/jpeg` and `image/png` are claimed here — the server still verifies the
 * magic bytes, and the array bound of the request schema is structural only, so
 * the service can answer `422 photo_limit_exceeded` instead of a body-limit `413`.
 */
export const photoDataUrlSchema = z
  .string()
  .regex(/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/]+={0,2}$/)

/**
 * Altcha proof-of-work payload sent back after a `400 captcha_required`
 * (`specs/06-report-form.md` §7.6, WP-M2-07c). The server verifies the challenge
 * hash and signature again; `maxnumber` and `took` are diagnostic fields of the
 * widget and are not needed to recompute the proof.
 */
export const altchaVerificationSchema = z.object({
  algorithm: z.literal('SHA-256'),
  challenge: z.string().min(1),
  salt: z.string().min(1),
  signature: z.string().min(1),
  number: z.number().int().min(0),
  maxnumber: z.number().int().positive().optional(),
  took: z.number().int().nonnegative().optional(),
  key: z.string().optional(),
})

export const publicReportRequestSchema = z.object({
  qrToken: qrTokenSchema,
  clientUuid: z.uuid(),
  title: trimmedText(200),
  text: trimmedText(4000),
  faultTemplateKeys: z
    .array(faultTemplateKeySchema)
    .max(9)
    .default([])
    .refine((keys) => new Set(keys).size === keys.length),
  contact: publicReportContactSchema.default({
    name: undefined,
    phone: undefined,
    email: undefined,
  }),
  /** Device capture time with offset; the server decides about the clock rule. */
  reportedAt: z.iso.datetime({ offset: true, local: true }).optional(),
  locale: z.enum(['de', 'en']).default('de'),
  /** Structural bound of 12; the semantic limit of 6 lives in the service (§7.4). */
  photos: z.array(photoDataUrlSchema).max(12).default([]),
  /** Hidden honeypot field (§7.6): absent/empty is human, filled flags spam. */
  website: z.string().optional(),
  /** Proof of work only asked for a suspicious report (§7.6, WP-M2-07c). */
  verification: altchaVerificationSchema.optional(),
  /**
   * The open ticket this report duplicates (`specs/06-report-form.md` §7.8.3,
   * WP-M2-08): the server accepts it only for a ticket of the same object and
   * stores it in `tickets.parent_ticket_id`.
   */
  parentTicketId: z.uuid().optional(),
})

export const publicReportResponseSchema = z.object({
  ticketId: z.uuid(),
  ticketNo: z.string(),
  status: z.literal('NEW'),
  statusToken: qrTokenSchema,
  reportedAt: z.iso.datetime(),
  receivedAt: z.iso.datetime(),
  deadlineAt: z.iso.datetime(),
  clockSkewed: z.boolean(),
  photoCount: z.number().int().min(0),
})

export type PublicReportContact = z.infer<typeof publicReportContactSchema>
export type PublicReportRequest = z.infer<typeof publicReportRequestSchema>
export type PublicReport = z.infer<typeof publicReportResponseSchema>
export type AltchaVerification = z.infer<typeof altchaVerificationSchema>

/**
 * Public status page (`specs/06-report-form.md` §7.3.4/§7.7, WP-M2-06).
 *
 * The status token is the only key of the page. The answer carries the ticket
 * number, the current status and the **public** part of the timeline — never
 * event payloads, actors, contact data or internal comments. The status values
 * mirror the database check of `specs/02-data-model.md` §4.8 and PLAN §7.
 */
export const TICKET_STATUS_VALUES = [
  'NEW',
  'IN_REVIEW',
  'WORK_ORDER_CREATED',
  'OFFERED',
  'ASSIGNED',
  'ACCEPTED',
  'ACKNOWLEDGED',
  'CLOSED',
  'CANCELLED',
] as const

export const ticketStatusSchema = z.enum(TICKET_STATUS_VALUES)

/** Only these event types are visible to the reporter; everything else stays internal. */
export const PUBLIC_TICKET_EVENT_TYPES = [
  'created',
  'work_order_set',
  'accepted',
  'acknowledged',
  'closed',
] as const

export const publicTicketEventSchema = z.object({
  type: z.enum(PUBLIC_TICKET_EVENT_TYPES),
  at: z.iso.datetime(),
})

export const publicTicketStatusResponseSchema = z.object({
  ticketNo: z.string(),
  status: ticketStatusSchema,
  reportedAt: z.iso.datetime(),
  deadlineAt: z.iso.datetime(),
  events: z.array(publicTicketEventSchema),
})

export type PublicTicketEvent = z.infer<typeof publicTicketEventSchema>
export type PublicTicketStatus = z.infer<typeof publicTicketStatusResponseSchema>

/**
 * Open tickets of an object (`specs/06-report-form.md` §7.8.1, WP-M2-08).
 *
 * "Open" is every status of the workflow of `PLAN.md` §7 except `CLOSED` and
 * `CANCELLED`: a ticket stays open from the report until the office closes it.
 */
export const OPEN_TICKET_STATUSES = [
  'NEW',
  'IN_REVIEW',
  'WORK_ORDER_CREATED',
  'OFFERED',
  'ASSIGNED',
  'ACCEPTED',
  'ACKNOWLEDGED',
] as const

export type OpenTicketStatus = (typeof OPEN_TICKET_STATUSES)[number]

export function isOpenTicketStatus(status: string): status is OpenTicketStatus {
  return (OPEN_TICKET_STATUSES as readonly string[]).includes(status)
}

/**
 * The duplicate hint (`specs/06-report-form.md` §7.8.1): the current QR token of
 * an active object resolves the object, `systemId` narrows the answer to one
 * system. The answer carries no description, no contact data and no
 * `status_token` — the hint shows number, status and time.
 */
export const publicOpenTicketsQuerySchema = z.object({
  qrToken: qrTokenSchema,
})

export const publicOpenTicketSchema = z.object({
  ticketId: z.uuid(),
  ticketNo: z.string(),
  status: ticketStatusSchema,
  reportedAt: z.iso.datetime(),
})

export const publicOpenTicketsResponseSchema = z.object({
  tickets: z.array(publicOpenTicketSchema),
})

/**
 * The public comment of the duplicate hint (`specs/06-report-form.md` §7.8.2):
 * the **QR token of the object** is the capability, so the server can check that
 * the ticket belongs to the object of the token. At least one of `text` and
 * `faultTemplateKeys` is required, exactly as in the report of §7.3.
 */
export const publicTicketCommentRequestSchema = z.object({
  qrToken: qrTokenSchema,
  clientUuid: z.uuid(),
  /** SEC-004: only the reporter who holds the ticket's status token may comment. */
  statusToken: qrTokenSchema,
  text: trimmedText(2000),
  faultTemplateKeys: z
    .array(faultTemplateKeySchema)
    .max(9)
    .default([])
    .refine((keys) => new Set(keys).size === keys.length),
  contact: publicReportContactSchema.default({
    name: undefined,
    phone: undefined,
    email: undefined,
  }),
  locale: z.enum(['de', 'en']).default('de'),
})

export const publicTicketCommentResponseSchema = z.object({
  ticketNo: z.string(),
  at: z.iso.datetime(),
})

/**
 * Internal ticket creation API (`PLAN.md` §7 rule 1, WP-M2-15).
 *
 * Authenticated endpoint for staff (`reporter_internal`, `office`, …). The
 * database generates `ticket_no` (§4.11) and `status_token` (§7.3.4); the
 * server sets `source = 'INTERNAL'` and `status = 'NEW'`.
 */

/** Meldungskanal einer intern erfassten Meldung (WP-M2-98). */
export const TICKET_REPORTER_CHANNELS = ['phone', 'email', 'messenger'] as const

/** Interner Mitarbeiter oder externe Person als Melder (WP-M2-98). */
export const TICKET_REPORTER_KINDS = ['internal', 'external'] as const

export const internalCreateTicketRequestSchema = z.object({
  objectId: z.uuid(),
  title: trimmedText(200),
  description: trimmedText(4000),
  faultTemplateKeys: z
    .array(faultTemplateKeySchema)
    .max(9)
    .default([])
    .refine((keys) => new Set(keys).size === keys.length),
  priority: z.enum(['low', 'normal', 'high', 'critical']).default('normal'),
  contact: publicReportContactSchema.optional(),
  /** Meldungskanal der Erfassung (WP-M2-98). */
  reporterChannel: z.enum(TICKET_REPORTER_CHANNELS).optional(),
  /** Interner Mitarbeiter oder externe Person (WP-M2-98). */
  reporterKind: z.enum(TICKET_REPORTER_KINDS).optional(),
  /** Der interne Benutzer, der die Meldung an den Erfasser gegeben hat. */
  reportedByUserId: z.uuid().optional(),
  /** Meldezeitpunkt mit Offset; der Server verhindert nur die Zukunft. */
  reportedAt: z.iso.datetime({ offset: true, local: true }).optional(),
})

/** Aktive interne Benutzer für die Melder-Auswahl (WP-M2-98b). */
export const reporterUserSchema = z.object({
  id: z.uuid(),
  name: z.string(),
  email: z.email(),
})

export const reporterUserListResponseSchema = z.object({
  users: z.array(reporterUserSchema),
})

export type ReporterUser = z.infer<typeof reporterUserSchema>
export type ReporterUserListResponse = z.infer<typeof reporterUserListResponseSchema>

export const internalCreateTicketResponseSchema = z.object({
  ticketId: z.uuid(),
  ticketNo: z.string(),
  status: z.string(),
  statusToken: z.string(),
  reportedAt: z.iso.datetime(),
  receivedAt: z.iso.datetime(),
  deadlineAt: z.iso.datetime(),
})

export type InternalCreateTicketRequest = z.infer<typeof internalCreateTicketRequestSchema>
export type InternalCreateTicketResponse = z.infer<typeof internalCreateTicketResponseSchema>

/** External ticket API (`specs/08-objects-api.md` §9.5, WP-M10-08). */
export const externalTicketCreateRequestSchema = internalCreateTicketRequestSchema
  .omit({ objectId: true })
  .extend({ objectNo: objectNoSchema })

export const externalTicketListQuerySchema = z.object({
  updated_since: z.iso.datetime().optional(),
  status: z.enum(['NEW', 'IN_REVIEW', 'WORK_ORDER_CREATED', 'OFFERED', 'ASSIGNED', 'ACCEPTED', 'ACKNOWLEDGED', 'CLOSED', 'CANCELLED']).optional(),
  objectNo: objectNoSchema.optional(),
  limit: z.coerce.number().int().min(1).max(1000).default(500),
})

export const workOrderRequestSchema = z.object({
  type: z.string().trim().min(1).max(40),
  number: z.string().trim().min(1).max(60),
})

/**
 * Close request (`specs/13-detected-errors.md` §13.3, WP-M11-04).
 *
 * Both fields are optional: a ticket can be closed without a comment and
 * without any detected error. `comment` is written as a `comment` event,
 * `detectedErrorKeys` is stored on `tickets.detected_error_keys`.
 */
export const closeRequestSchema = z.object({
  comment: z.string().trim().max(2000).optional().transform((value) => (value === '' ? undefined : value)),
  detectedErrorKeys: z
    .array(z.string().trim().min(1).max(100))
    .max(20)
    .default([])
    .transform((value) => (value.length === 0 ? undefined : value)),
})

export type CloseRequest = z.infer<typeof closeRequestSchema>

export type ExternalTicketCreateRequest = z.infer<typeof externalTicketCreateRequestSchema>
export type ExternalTicketListQuery = z.infer<typeof externalTicketListQuerySchema>
export type WorkOrderRequest = z.infer<typeof workOrderRequestSchema>

export type PublicOpenTicket = z.infer<typeof publicOpenTicketSchema>
export type PublicOpenTickets = z.infer<typeof publicOpenTicketsResponseSchema>
export type PublicTicketCommentRequest = z.infer<typeof publicTicketCommentRequestSchema>
export type PublicTicketComment = z.infer<typeof publicTicketCommentResponseSchema>

/**
 * Ticket list API (`PLAN.md` §6, WP-M2-17).
 *
 * Authenticated `GET /api/v1/tickets` for staff. Paginated list with object
 * number/name, status, priority, reportedAt and deadlineAt. Filters: search
 * (object number / name), status, objectId, priority.
 */

export const ticketListQuerySchema = z.object({
  search: z.string().trim().max(200).optional(),
  status: z.enum(['NEW', 'IN_REVIEW', 'WORK_ORDER_CREATED', 'OFFERED', 'ASSIGNED', 'ACCEPTED', 'ACKNOWLEDGED', 'CLOSED', 'CANCELLED']).optional(),
  objectId: z.uuid().optional(),
  priority: z.enum(['low', 'normal', 'high', 'critical']).optional(),
  /** Open means: the status is neither CLOSED nor CANCELLED (`specs/06-report-form.md` §7.8). */
  open: z
    .enum(['true', 'false'])
    .optional()
    .transform((value) => (value === undefined ? undefined : value === 'true')),
  /** Overdue means: the deadline is in the past and the ticket is still open. */
  overdue: z
    .enum(['true', 'false'])
    .optional()
    .transform((value) => (value === undefined ? undefined : value === 'true')),
  order: z.enum(['reportedAt', 'deadlineAt', 'priority']).default('reportedAt'),
  direction: z.enum(['asc', 'desc']).default('desc'),
  limit: z.coerce.number().min(1).max(100).default(25),
  offset: z.coerce.number().min(0).default(0),
})

export const ticketTimelineStateSchema = z.enum(['green', 'yellow', 'orange', 'red', 'stopped'])

export const ticketPauseSchema = z.object({
  id: z.uuid(),
  ticketId: z.uuid(),
  reason: z.string(),
  startedAt: z.iso.datetime(),
  endedAt: z.iso.datetime().nullable(),
  startedByUserId: z.uuid().nullable(),
  endedByUserId: z.uuid().nullable(),
  createdAt: z.iso.datetime(),
})

export const ticketTimelineMarkerSchema = z.object({
  type: z.string(),
  at: z.iso.datetime(),
})

export const ticketTimelineSchema = z.object({
  reportedAt: z.iso.datetime(),
  deadlineAt: z.iso.datetime(),
  stoppedAt: z.iso.datetime().nullable(),
  pausedMs: z.number().nonnegative(),
  totalMs: z.number().nonnegative(),
  elapsedMs: z.number().nonnegative(),
  remainingMs: z.number().nonnegative(),
  percent: z.number().min(0).max(100),
  state: ticketTimelineStateSchema,
  pause: ticketPauseSchema.pick({ id: true, reason: true, startedAt: true }).nullable(),
  markers: z.array(ticketTimelineMarkerSchema),
})

export const ticketListItemSchema = z.object({
  id: z.uuid(),
  ticketNo: z.string(),
  objectNo: z.string(),
  objectName: z.string(),
  status: z.string(),
  priority: z.string(),
  reportedAt: z.iso.datetime(),
  deadlineAt: z.iso.datetime(),
  timelineState: ticketTimelineStateSchema,
  percent: z.number().min(0).max(100),
  remainingMs: z.number().nonnegative(),
})

export const ticketListResponseSchema = z.object({
  tickets: z.array(ticketListItemSchema),
  total: z.number(),
  limit: z.number(),
  offset: z.number(),
})

export type TicketListQuery = z.infer<typeof ticketListQuerySchema>
export type TicketListResponse = z.infer<typeof ticketListResponseSchema>
export type TicketListItem = z.infer<typeof ticketListItemSchema>

/**
 * Ticket detail API (`PLAN.md` §6/§7, WP-M2-18a).
 *
 * Authenticated `GET /api/v1/tickets/:ticketNo` for staff. Returns the ticket
 * with object info, the append-only event history and photo metadata.
 */

export const ticketDetailResponseSchema = z.object({
  ticket: z.object({
    id: z.uuid(),
    ticketNo: z.string(),
    objectNo: z.string(),
    objectName: z.string(),
    status: z.string(),
    priority: z.string(),
    title: z.string().nullable(),
    description: z.string().nullable(),
    faultTemplateKeys: z.array(z.string()),
    source: z.string(),
    reportedAt: z.iso.datetime(),
    receivedAt: z.iso.datetime(),
    deadlineAt: z.iso.datetime(),
    reporterName: z.string().nullable(),
    reporterPhone: z.string().nullable(),
    reporterEmail: z.string().nullable(),
    /** Name of the user who recorded the ticket, or null (e. g. QR / e-mail report). */
    recordedBy: z.string().nullable(),
    statusToken: z.string().nullable(),
  }),
  events: z.array(
    z.object({
      id: z.uuid(),
      type: z.string(),
      actorKind: z.string(),
      actorName: z.string().nullable(),
      payload: z.record(z.string(), z.unknown()).default({}),
      createdAt: z.iso.datetime(),
    }),
  ),
  photos: z.array(
    z.object({
      id: z.uuid(),
      filePath: z.string(),
      mimeType: z.string(),
      sizeBytes: z.number(),
      createdAt: z.iso.datetime(),
    }),
  ),
  timeline: ticketTimelineSchema,
  pauses: z.array(ticketPauseSchema),
  /**
   * The stages the ticket can still reach (`specs/07-escalation.md` §7.10).
   * The view offers them instead of one button per workflow step; `events`
   * names the workflow transitions that reach the stage.
   */
  availableStages: z.array(
    z.object({
      key: z.string(),
      names: z.record(z.string(), z.string()),
      events: z.array(z.string()),
    }),
  ),
})

export type TicketDetailResponse = z.infer<typeof ticketDetailResponseSchema>


/**
 * Manual escalation write (`specs/07-escalation.md` §7.5, WP-M12-05).
 *
 * `stageKey = null` writes a comment; a known stage key writes one
 * `escalation_set` event. The text is required in both cases.
 */
export const manualEscalationRequestSchema = z.object({
  stageKey: z.string().min(1).max(40).nullable(),
  text: z.string().trim().min(1).max(2000),
})

export type ManualEscalationRequest = z.infer<typeof manualEscalationRequestSchema>
